alter table public.services add column if not exists moderation_status text not null default 'draft', add column if not exists moderation_reason text, add column if not exists submitted_at timestamptz, add column if not exists reviewed_at timestamptz, add column if not exists reviewed_by uuid;
update public.services set moderation_status='approved' where moderation_status='draft' and created_at < now();
alter table public.reservations add column if not exists service_delivery_status text not null default 'scheduled', add column if not exists settlement_status text not null default 'not_applicable', add column if not exists athlete_confirmed_at timestamptz, add column if not exists provider_marked_completed_at timestamptz, add column if not exists auto_confirm_after timestamptz, add column if not exists dispute_opened_at timestamptz, add column if not exists dispute_reason text, add column if not exists settlement_released_at timestamptz;
create table if not exists public.service_moderation_events(id uuid primary key default gen_random_uuid(),service_id uuid not null references public.services(id) on delete cascade,event_type text not null,actor_user_id uuid,note text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.reservation_delivery_events(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references public.reservations(id) on delete cascade,event_type text not null,actor_user_id uuid,note text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists reservations_delivery_due_idx on public.reservations(service_delivery_status,settlement_status,auto_confirm_after);
